'use strict';
const $ = id => document.getElementById(id);
const missions = [
  { title:'Hari di taman', scene:'garden', target:30, reference:10, direction:'higher', story:'Bayangkan suhu di taman ialah <strong>30°C.</strong>', explanation:'30°C lebih tinggi daripada 10°C. Apabila suhu meningkat, aras cecair naik.', question:'Yang manakah mempunyai suhu lebih tinggi?', answers:['10°C','30°C'], answer:1 },
  { title:'Ais yang membeku', scene:'ice', target:0, reference:20, direction:'lower', story:'Air tulen membeku pada <strong>0°C</strong> pada tekanan biasa.', explanation:'0°C lebih rendah daripada 20°C. Apabila suhu menurun, aras cecair turun.', question:'Yang manakah mempunyai suhu lebih rendah?', answers:['0°C','20°C'], answer:0 },
  { title:'Sudut bacaan', scene:'room', target:20, reference:30, direction:'lower', story:'Bayangkan suhu bilik bacaan ialah <strong>20°C.</strong>', explanation:'20°C lebih rendah daripada 30°C. Nombor lebih kecil menunjukkan suhu lebih rendah.', question:'Berapa beza antara 30°C dan 20°C?', answers:['10°C','20°C'], answer:0 }
];
let temperature=10, missionIndex=0, phase='predict', mode='mission', prediction=null, soundOn=false, audioContext=null, hintCount=0;
const sceneNames={ice:'Ais membeku',room:'Sudut bacaan',garden:'Hari di taman'};
const sceneDescriptions={ice:'Ilustrasi ais dalam mangkuk di atas permukaan biru',room:'Ilustrasi ruang bacaan dengan tumbuhan dan tingkap',garden:'Ilustrasi taman yang cerah dengan pokok dan tikar berkelah'};
const sceneIcons={ice:'i-snow',room:'i-leaf',garden:'i-sun'};
const yAt=t=> 302 - ((t+10)/60)*264;
for(let t=-10;t<=50;t+=5){const y=yAt(t);const major=t%10===0;$('ticks').insertAdjacentHTML('beforeend',`<path d="M${major?78:88} ${y}h${major?22:12}" stroke="#887cab" stroke-width="${major?2:1.5}"/>${major?`<text x="69" y="${y+5}" text-anchor="end">${t===-10?'−10':t}</text>`:''}`);}
function playTone(success){if(!soundOn)return;try{audioContext??=new(window.AudioContext||window.webkitAudioContext)();audioContext.resume();const now=audioContext.currentTime;[success?523:330,success?659:294,success?784:262].forEach((freq,i)=>{const osc=audioContext.createOscillator(),gain=audioContext.createGain();osc.type='sine';osc.frequency.value=freq;gain.gain.setValueAtTime(.08,now+i*.13);gain.gain.exponentialRampToValueAtTime(.001,now+i*.13+.22);osc.connect(gain);gain.connect(audioContext.destination);osc.start(now+i*.13);osc.stop(now+i*.13+.23);});}catch{soundOn=false;syncSound();}}
function syncSound(){$('sound').setAttribute('aria-pressed',String(soundOn));$('sound').setAttribute('aria-label',soundOn?'Matikan bunyi':'Hidupkan bunyi');document.querySelector('.sound-state').textContent=soundOn?'on':'off';}
function setScene(scene){$('scene').className='scene scene-'+scene;$('scene').setAttribute('aria-label',sceneDescriptions[scene]);$('scene-title').textContent=sceneNames[scene];document.querySelector('.scene-tag use').setAttribute('href','#'+sceneIcons[scene]);document.querySelector('#weather-icon use').setAttribute('href','#'+sceneIcons[scene]);}
function updateTemperature(value){temperature=Math.max(-10,Math.min(50,Number(value)));$('slider').value=temperature;$('slider').setAttribute('aria-valuetext',`${temperature} darjah Celsius`);$('temperature').textContent=temperature<0?'−'+Math.abs(temperature):temperature;$('f-reading').textContent=`${Number((temperature*9/5+32).toFixed(1))}°F`;const y=yAt(temperature);$('liquid').setAttribute('y',y);$('liquid').setAttribute('height',Math.max(13,319-y));$('level-marker').setAttribute('transform',`translate(0 ${y})`);setScene(temperature<=0?'ice':temperature<25?'room':'garden');$('feeling').textContent=temperature<=0?'Sangat sejuk':temperature<15?'Lebih sejuk':temperature<25?'Suhu sederhana':'Lebih panas';$('context-copy').textContent=temperature===0?'Air tulen boleh membeku pada 0°C.':temperature<0?'Suhu ini lebih rendah daripada 0°C.':temperature<25?'Bandingkan aras cecair dengan suhu yang lebih tinggi.':'Nombor lebih besar. Aras cecair lebih tinggi!';const unlocked=mode==='explore'||phase==='adjust';$('minus').disabled=!unlocked||temperature<=-10;$('plus').disabled=!unlocked||temperature>=50;}
function setUnlocked(enabled){$('slider').disabled=!enabled;document.querySelectorAll('[data-temp]').forEach(b=>b.disabled=!enabled);$('lock-hint').textContent=enabled?'Seret atau tekan − / +':phase==='predict'?'Buat ramalan dahulu':'Suhu sudah disemak';updateTemperature(temperature);}
function setPhase(newPhase){phase=newPhase;document.body.dataset.phase=phase;document.body.dataset.mode=mode;const steps=['predict','adjust','explain'];document.querySelectorAll('[data-phase]').forEach((li,i)=>{li.classList.toggle('current',li.dataset.phase===phase);li.classList.toggle('done',i<steps.indexOf(phase)||phase==='complete');});$('prediction-section').hidden=phase!=='predict';$('adjust-section').hidden=phase!=='adjust';$('explain-section').hidden=phase!=='explain';$('check').hidden=phase!=='predict'&&phase!=='adjust';$('check').disabled=phase!=='adjust';$('next').hidden=phase!=='complete';setUnlocked(phase==='adjust'||mode==='explore');}
function feedback(text,good=false){$('feedback').hidden=false;$('feedback').className='feedback'+(good?' good':'');$('feedback').textContent=text;}
function celebrate(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const colours=['#286346','#ec6559','#655d91','#f1b636'];$('celebration').replaceChildren();for(let i=0;i<24;i++){const s=document.createElement('span');s.className='confetti';s.style.background=colours[i%4];s.style.setProperty('--x',`${Math.cos(i*.8)*(140+i*9)}px`);s.style.setProperty('--y',`${Math.sin(i*.8)*120+200}px`);s.style.setProperty('--r',`${i*53}deg`);$('celebration').append(s);}setTimeout(()=>$('celebration').replaceChildren(),1500);}
function renderMission(){const m=missions[missionIndex];prediction=null;hintCount=0;$('mission-title').textContent=m.title;$('mission-story').innerHTML=m.story;$('mission-count').textContent=`Misi ${missionIndex+1} daripada 3`;document.querySelector('#mission-icon use').setAttribute('href','#'+sceneIcons[m.scene]);$('prediction-question').textContent=`Berbanding ${m.reference}°C, aras cecair pada ${m.target}°C akan…`;$('adjust-instruction').innerHTML=`Laras termometer kepada <strong>${m.target}°C</strong>, kemudian semak jawapan.`;$('feedback').hidden=true;$('hint-text').hidden=true;$('hint').hidden=false;document.querySelectorAll('[data-prediction]').forEach(b=>{b.classList.remove('selected');b.disabled=false;});$('next').innerHTML=missionIndex===2?'Teroka lagi <svg><use href="#i-arrow"/></svg>':'Misi seterusnya <svg><use href="#i-arrow"/></svg>';$('target-marker').setAttribute('hidden','');$('target-marker').style.display='none';updateTemperature(m.reference);setPhase('predict');updateStars();}
function updateStars(){document.querySelectorAll('.stars svg').forEach((s,i)=>s.classList.toggle('completed',i<missionIndex||(i===missionIndex&&phase==='complete')));document.querySelector('.stars').setAttribute('aria-label',`${missionIndex+(phase==='complete'?1:0)} daripada 3 misi selesai`);}
document.querySelectorAll('[data-prediction]').forEach(button=>button.addEventListener('click',()=>{if(mode!=='mission'||phase!=='predict')return;prediction=button.dataset.prediction;document.querySelectorAll('[data-prediction]').forEach(b=>b.classList.toggle('selected',b===button));setPhase('adjust');feedback('Ramalan dicatat. Sekarang laraskan suhu untuk menguji ramalan kamu.');$('slider').focus();}));
function setValue(value){if(mode==='mission'&&phase!=='adjust')return;updateTemperature(value);if(phase==='adjust')$('feedback').hidden=true;}
$('slider').addEventListener('input',e=>setValue(e.target.value));$('minus').addEventListener('click',()=>setValue(temperature-1));$('plus').addEventListener('click',()=>setValue(temperature+1));document.querySelectorAll('[data-temp]').forEach(b=>b.addEventListener('click',()=>setValue(b.dataset.temp)));
$('check').addEventListener('click',()=>{if(phase!=='adjust')return;const m=missions[missionIndex];if(temperature!==m.target){const diff=m.target-temperature;feedback(`Bacaan kamu ${temperature}°C. Sasaran ialah ${m.target}°C. ${diff>0?'Naikkan':'Turunkan'} suhu sebanyak ${Math.abs(diff)}°C dan cuba semula.`);$('target-marker').style.display='';$('target-marker').removeAttribute('hidden');$('target-marker').setAttribute('transform',`translate(0 ${yAt(m.target)})`);$('feedback').setAttribute('tabindex','-1');$('feedback').focus();playTone(false);return;}setPhase('explain');$('target-marker').style.display='none';$('target-marker').setAttribute('hidden','');feedback(`${prediction===m.direction?'Ramalan kamu tepat!':'Mari betulkan ramalan tadi.'} ${m.explanation}`,true);$('explain-question').textContent=m.question;$('explain-choices').replaceChildren();m.answers.forEach((answer,i)=>{const button=document.createElement('button');button.textContent=answer;button.addEventListener('click',()=>{if(phase!=='explain')return;if(i!==m.answer){feedback(`Cuba lagi. ${m.explanation}${missionIndex===2?' Kira 30 − 20.':''}`);playTone(false);return;}setPhase('complete');$('explain-section').hidden=false;button.classList.add('selected');$('explain-choices').querySelectorAll('button').forEach(b=>b.disabled=true);feedback(missionIndex===2?'Hebat! Kamu sudah selesai 3 misi. Suhu naik, aras naik; suhu turun, aras turun.':'Betul! Kamu sudah faham. Jom cuba misi seterusnya.',true);$('hint').hidden=true;$('hint-text').hidden=true;updateStars();celebrate();playTone(true);$('next').focus();});$('explain-choices').append(button);});playTone(true);$('explain-choices').querySelector('button').focus();});
$('next').addEventListener('click',()=>{if(phase!=='complete')return;if(missionIndex===2){setMode('explore');return;}missionIndex++;renderMission();$('higher').focus();});
$('hint').addEventListener('click',()=>{hintCount++;const m=missions[missionIndex];$('hint-text').hidden=false;if(mode==='explore')$('hint-text').textContent='Cuba 0°C, 20°C dan 30°C. Bandingkan aras cecair pada setiap bacaan.';else if(phase==='predict')$('hint-text').textContent=`Bandingkan nombor ${m.target} dengan ${m.reference}. Nombor lebih besar bermaksud suhu lebih tinggi.`;else if(phase==='adjust')$('hint-text').textContent=hintCount>1?`Cari tanda ${m.target}°C pada skala. Kamu juga boleh menggunakan butang suhu contoh.`:`Hujung cecair menunjukkan bacaan. Sasaran kamu ialah ${m.target}°C.`;else $('hint-text').textContent=missionIndex===2?'Beza suhu = 30 − 20.':m.explanation;});
function setMode(nextMode){mode=nextMode;const explore=mode==='explore';$('explore-mode').classList.toggle('active',explore);$('explore-mode').setAttribute('aria-pressed',String(explore));$('mission-mode').classList.toggle('active',!explore);$('mission-mode').setAttribute('aria-pressed',String(!explore));document.querySelector('.learning-path').hidden=explore;if(!explore){missionIndex=0;renderMission();return;}setPhase('adjust');$('prediction-section').hidden=true;$('adjust-section').hidden=true;$('explain-section').hidden=true;$('check').hidden=true;$('next').hidden=true;$('feedback').hidden=true;$('hint-text').hidden=true;$('hint').hidden=false;$('target-marker').style.display='none';$('mission-count').textContent='Teroka mengikut rentak kamu';$('mission-title').textContent='Apa yang berubah?';$('mission-story').innerHTML='Gerakkan pelaras. Perhatikan <strong>nombor suhu</strong> dan <strong>aras cecair.</strong>';$('adjust-section').hidden=false;$('adjust-section').innerHTML='<h3>Cuba tiga suhu ini.</h3><p id="adjust-instruction">Mulakan dengan 0°C, kemudian 20°C dan 30°C. Suhu manakah yang paling tinggi?</p>';document.querySelector('#mission-icon use').setAttribute('href','#i-thermo');feedback('Kamu mengawal suhu! Gunakan butang − / + untuk perubahan 1°C.',true);setUnlocked(true);}
$('explore-mode').addEventListener('click',()=>setMode('explore'));$('mission-mode').addEventListener('click',()=>{restoreAdjust();setMode('mission');});
function restoreAdjust(){$('adjust-section').innerHTML='<h3>Sekarang, cuba sendiri.</h3><p id="adjust-instruction"></p>';}
$('restart').addEventListener('click',()=>{restoreAdjust();missionIndex=0;setMode('mission');$('higher').focus();});
$('fahrenheit').addEventListener('click',()=>{const show=$('f-reading').hidden;$('f-reading').hidden=!show;$('fahrenheit').setAttribute('aria-pressed',String(show));$('fahrenheit').textContent=show?'Sembunyikan °F':'Lihat °F juga';});
$('sound').addEventListener('click',()=>{soundOn=!soundOn;syncSound();if(soundOn)playTone(true);});$('help').addEventListener('click',()=>{const show=$('help-panel').hidden;$('help-panel').hidden=!show;$('help').setAttribute('aria-expanded',String(show));});
renderMission();




